     "label": "Where",
     "kind": "choice",
     "required": false,
     "choices": [
      "Fridge",
      "Freezer",
      "Pantry",
      "Spice rack"
     ],
     "unit": null,
     "defaultValue": "Pantry",
     "linkCollectionId": null,
